# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">1. PROBLEM: VARLIĞIN VAR OLUP OLMADIĞI PROBLEMİ (FEL.10.3.1)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">NİHİLİZM (HİÇÇİLİK) VE TAOİZM</text>\n  <text x="35" y="88" font-size="11" font-weight="bold" fill="#7f1d1d">Temel Sav: Gerçek bir varlık yoktur!</text>\n  <text x="35" y="110" font-size="10.8" fill="#7f1d1d">• Gorgias (Sofist): «Hiçbir şey yoktur; olsa da</text>\n  <text x="35" y="128" font-size="10.8" fill="#7f1d1d">  bilinemez; bilinse de başkasına aktarılamaz.»</text>\n  <text x="35" y="150" font-size="10.8" fill="#7f1d1d">• Lao Tse (Taoizm): Dış dünyadaki çokluk aldatıcı</text>\n  <text x="35" y="168" font-size="10.8" fill="#7f1d1d">  görüntülerdir; tek gerçeklik şekilsiz \'Tao\'dur.</text>\n  <text x="35" y="190" font-size="10.5" fill="#991b1b">• Varlığın nesnel gerçekliğini ve bilgisini reddeder.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">REALİZM (GERÇEKÇİLİK)</text>\n  <text x="370" y="88" font-size="11" font-weight="bold" fill="#14532d">Temel Sav: Varlık vardır!</text>\n  <text x="370" y="110" font-size="10.8" fill="#14532d">• İnsan zihninden bağımsız nesnel bir gerçeklik</text>\n  <text x="370" y="128" font-size="10.8" fill="#14532d">  veya düşünsel bir varlık alanı mevcuttur.</text>\n  <text x="370" y="150" font-size="10.8" fill="#14532d">• Varlığı kabul eden filozoflar bu kez «Varlık</text>\n  <text x="370" y="168" font-size="10.8" fill="#14532d">  nedir? Ana maddesi (arkhe) nedir?» sorusunu sorar.</text>\n  <text x="370" y="190" font-size="10.5" fill="#166534">• Oluş, İdea, Madde, Düalizm ve Fenomen yaklaşımları.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Ontolojinin ilk sorusu «Varlık var mıdır?» sorusudur; verilen yanıt diğer tüm felsefi tutumu belirler.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="24" text-anchor="middle" font-size="13.8" font-weight="bold" fill="#0f172a">2. PROBLEM: VARLIĞIN NE OLDUĞU PROBLEMİ (5 TEMEL YAKLAŞIM)</text>\n  <rect x="16" y="38" width="128" height="178" rx="8" fill="#fff7ed" stroke="#ea580c" stroke-width="1.8"/>\n  <text x="80" y="58" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">1. OLUŞ</text>\n  <text x="80" y="76" text-anchor="middle" font-size="9.8" fill="#7c2d12">Herakleitos</text>\n  <text x="80" y="92" text-anchor="middle" font-size="9.8" fill="#7c2d12">Whitehead</text>\n  <text x="24" y="114" font-size="9.5" fill="#7c2d12">• Durağan varlık</text>\n  <text x="24" y="129" font-size="9.5" fill="#7c2d12">  yoktur, değişim</text>\n  <text x="24" y="144" font-size="9.5" fill="#7c2d12">  ve akış vardır.</text>\n  <text x="24" y="164" font-size="9.5" fill="#7c2d12">• Arkhe: Ateş</text>\n  <text x="24" y="180" font-size="9.5" fill="#7c2d12">• Düzen: Logos</text>\n  <rect x="152" y="38" width="128" height="178" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="216" y="58" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">2. İDEA</text>\n  <text x="216" y="76" text-anchor="middle" font-size="9.8" fill="#1e3a8a">Platon, Aristo</text>\n  <text x="216" y="92" text-anchor="middle" font-size="9.8" fill="#1e3a8a">Farabi, Hegel</text>\n  <text x="160" y="114" font-size="9.5" fill="#1e3a8a">• Asıl varlık</text>\n  <text x="160" y="129" font-size="9.5" fill="#1e3a8a">  düşünsel/tinsel</text>\n  <text x="160" y="144" font-size="9.5" fill="#1e3a8a">  türdendir.</text>\n  <text x="160" y="164" font-size="9.5" fill="#1e3a8a">• İdealar, Form,</text>\n  <text x="160" y="180" font-size="9.5" fill="#1e3a8a">  Geist (Tin)</text>\n  <rect x="288" y="38" width="128" height="178" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="352" y="58" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">3. MADDE</text>\n  <text x="352" y="76" text-anchor="middle" font-size="9.8" fill="#14532d">Demokritos, Marx</text>\n  <text x="352" y="92" text-anchor="middle" font-size="9.8" fill="#14532d">Hobbes, La Mettrie</text>\n  <text x="296" y="114" font-size="9.5" fill="#14532d">• Varlığın temeli</text>\n  <text x="296" y="129" font-size="9.5" fill="#14532d">  atom ve maddedir.</text>\n  <text x="296" y="144" font-size="9.5" fill="#14532d">• Düşünce maddenin</text>\n  <text x="296" y="159" font-size="9.5" fill="#14532d">  ürünüdür.</text>\n  <text x="296" y="179" font-size="9.5" fill="#14532d">• Mekanik &amp; Diyalektik</text>\n  <rect x="424" y="38" width="128" height="178" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="488" y="58" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">4. İDEA-MADDE</text>\n  <text x="488" y="76" text-anchor="middle" font-size="9.8" fill="#581c87">Descartes</text>\n  <text x="488" y="92" text-anchor="middle" font-size="9.8" fill="#581c87">(Düalizm / İkicilik)</text>\n  <text x="432" y="114" font-size="9.5" fill="#581c87">• İki indirgenemez</text>\n  <text x="432" y="129" font-size="9.5" fill="#581c87">  cevher (töz):</text>\n  <text x="432" y="149" font-size="9.5" fill="#581c87">1) Ruh (Düşünen)</text>\n  <text x="432" y="166" font-size="9.5" fill="#581c87">2) Madde (Yer</text>\n  <text x="432" y="181" font-size="9.5" fill="#581c87">   kaplayan / Uzam)</text>\n  <rect x="560" y="38" width="124" height="178" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="622" y="58" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">5. FENOMEN</text>\n  <text x="622" y="76" text-anchor="middle" font-size="9.8" fill="#78350f">Edmund Husserl</text>\n  <text x="622" y="92" text-anchor="middle" font-size="9.8" fill="#78350f">(Fenomenoloji)</text>\n  <text x="568" y="114" font-size="9.5" fill="#78350f">• Varlık, bilincin</text>\n  <text x="568" y="129" font-size="9.5" fill="#78350f">  yöneldiği özdür.</text>\n  <text x="568" y="149" font-size="9.5" fill="#78350f">• Paranteze alma</text>\n  <text x="568" y="166" font-size="9.5" fill="#78350f">  (Epokhe) yöntemi</text>\n  <text x="568" y="181" font-size="9.5" fill="#78350f">  ile öze ulaşılır.</text>\n  <rect x="16" y="224" width="668" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Tek ilkeli yaklaşımlara Monizm (İdealizm, Materyalizm), iki ilkeli yaklaşıma Düalizm (Descartes) denir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">ÇAĞDAŞ ONTOLOJİ VE VAROLUŞÇULUK (EGZİSTANSİYALİZM)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Y. ONTOLOJİ (NICOLAI HARTMANN)</text>\n  <text x="35" y="88" font-size="10.8" fill="#1e3a8a">• Varlığı deneysel ve gerçek temelde inceler.</text>\n  <text x="35" y="108" font-size="10.8" fill="#1e3a8a">• Varlık 4 katmandan (tabakadan) oluşur:</text>\n  <text x="45" y="128" font-size="10.5" fill="#1e3a8a">1. İnorganik (Cansız) Katman — Fizik</text>\n  <text x="45" y="146" font-size="10.5" fill="#1e3a8a">2. Organik (Canlı) Katman — Biyoloji</text>\n  <text x="45" y="164" font-size="10.5" fill="#1e3a8a">3. Ruhsal (Bilinçli) Katman — Psikoloji</text>\n  <text x="45" y="182" font-size="10.5" fill="#1e3a8a">4. Tinsel (Manevi/Kültürel) Katman — Felsefe</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">VAROLUŞÇULUK (KIERKEGAARD, SARTRE)</text>\n  <text x="370" y="88" font-size="10.8" fill="#064e3b">• Sartre: «İnsanda varoluş özden önce gelir.»</text>\n  <text x="370" y="108" font-size="10.8" fill="#064e3b">• Nesnelerin özü (tasarımı) varoluşundan öncedir.</text>\n  <text x="370" y="128" font-size="10.8" fill="#064e3b">• İnsan ise önce dünyaya gelir (var olur), sonra</text>\n  <text x="370" y="146" font-size="10.8" fill="#064e3b">  özgür seçimleriyle kendi özünü kendisi kurar.</text>\n  <text x="370" y="166" font-size="10.8" fill="#064e3b">• İnsan özgürlüğe mahkûmdur ve seçimlerinden</text>\n  <text x="370" y="184" font-size="10.8" fill="#064e3b">  bütünüyle sorumludur.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Felsefi metin analizinde filozofun kullandığı kavramlar, ele aldığı problem ve sunduğu argümanlar birlikte çözümlenir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
